  "predicate_classification": {
    "convention": "Per-command classification of the 87 is impossible: the authoritative command list is absent from this packet. Every inherited command is therefore conservatively classified Windows-owned until its authoritative definition is bound and a predicate-level review proves otherwise.",
    "intrinsically_windows_or_path_bound": [
      {
        "predicate_family": "windows-receipt-path",
        "meaning": "Checks that assert receipt/artifact existence or content at Windows-native paths inside the gate's own receipt store. A WSL process can observe those bytes through /mnt/c but cannot truthfully emit a receipt whose executing path identity is Windows-native.",
        "evidence": "policy-revision-02.json historical_gate_portability; validation-contract.json full_gate_blocker"
      },
      {
        "predicate_family": "windows-host-identity",
        "meaning": "Checks that bind the gate outcome to execution on the Windows host itself (Windows platform identity, Windows-qualified interpreter/toolchain, Windows-side working tree). Cannot be satisfied by Linux execution without faking host identity, which is forbidden.",
        "evidence": "policy-revision-02.json historical_gate_portability; validation-contract.json full_gate_blocker"
      },
      {
        "predicate_family": "windows-qualified-lint-route",
        "meaning": "Windows Ruff is the qualified lint route. A native lint run is additionally impossible today: construction-checkpoint-gate-01 FAILed because Ruff is not installed in the native environment. No wsl-ruff supplemental may be planned or claimed.",
        "evidence": "publication-workflow-status-01.json checkpoint_gates qualification and construction-checkpoint-gate-01 retained_reason"
      },
      {
        "predicate_family": "windows-measured-timing-envelope",
        "meaning": "The 4800-second per-gate admission window and the 10200-second finalization reserve are derived from Windows-measured final87 durations (3771.077387s and 3576.111586s). WSL timings would be new observations, not the inherited envelope.",
        "evidence": "policy-revision-02.json reason"
      },
      {
        "predicate_family": "per-command-unknown",
        "meaning": "The argv, cwd, environment, timeout and receipt shape of each of the 87 commands (including which 50 are Batch07) are not in tracked evidence. They are UNRESOLVED and must be imported from the authoritative inherited gate definition before any manifest is executable; none may be invented.",
        "evidence": "absence across all packet files; charter.json validation_obligation is the only cardinality statement"
      }
    ],
    "wsl_supplemental_duplicable": [
      {
        "check": "complete unit suite (wsl-unittest)",
        "note": "Already runs natively: 70 tests with 1 platform skip on WSL versus 7 platform skips on Windows, so the effective exercised set differs. Report WSL counts as WSL evidence; never claim equivalent coverage.",
        "evidence": "publication-workflow-status-01.json checkpoint_gates observed_counts"
      },
      {
        "check": "source-only py_compile of scientific files (wsl-source-pycompile)",
        "note": "Already the native treatment for source-only scientific files.",
        "evidence": "publication-workflow-status-01.json checkpoint_gates"
      },
      {
        "check": "diff-check, exact-clean worktree, branch/HEAD/tree and ancestry checks",
        "note": "Host-neutral git facts; the controller proposal already enforces them natively against the exact candidate.",
        "evidence": "controller-proposal-01/native_local.py scope(); publication-workflow-status-01.json diff-check"
      },
      {
        "check": "native admission -> nonrefundable reservation -> sandboxed run -> controller-owned retained audit chain",
        "note": "Produces PASS_LOCAL_RESEARCH_ONLY receipts carrying full_gate_equivalence=false and scientific_approval=false. Partial scientific validation only.",
        "evidence": "controller-proposal-01/native_local.py EXECUTION_KEYS/status constants; validation-contract.json full_gate_blocker"
      },
      {
        "check": "PAUSE/STOP marker and active-parent observation including the Windows repo via /mnt/c",
        "note": "Observation only: the native side can read the Windows tree through the mount but cannot execute Windows commands from it.",
        "evidence": "controller-proposal-01/native_local.py marker_paths() and WINDOWS_REPO"
      }
    ],
    "receipt_identities_that_must_remain_windows_owned": [
      "The two complete inherited gate receipts (the full87 gate pair) and the gate-pair ledger reservation identity (purpose inherited-full-gate-pair, 655520 units, ordinal 0, exactly once).",
      "Each of the 87 per-command receipts inside each gate, including all 50 Batch07 command receipts.",
      "The windows-ruff qualified lint receipt identity.",
      "Any receipt asserting Windows host identity or a Windows receipt path.",
      "The label full87 itself: native local checks must not be called the full87 gate and native PASS receipts cannot satisfy or impersonate it."
    ]
  },

  "two_host_manifest": {
    "schema": "recursion-two-host-gate-manifest/v1",
    "purpose": "One candidate-bound manifest under which a successor gate can preserve all 87 Windows-owned inherited commands while adding native checker/controls/retained-audit commands, without conflating receipt ownership.",
    "required_keys": ["schema", "campaign", "parent_goal", "candidate", "candidate_tree", "manifest_id", "hosts", "command_source", "windows_commands", "native_supplemental_checks", "native_added_commands_ref", "binding_rules", "ready", "blocking"],
    "hosts": {
      "windows-primary": {
        "role": "inherited-gate-owner",
        "repo_native_form": "C:\\Users\\Lucas\\Documents\\GitHub\\recursion",
        "wsl_observation_alias": "/mnt/c/Users/Lucas/Documents/GitHub/recursion",
        "identity_evidence_required": ["executing-OS Windows observation captured at runtime", "repo path recorded in native Windows form", "host capture embedded in each gate receipt"]
      },
      "wsl-native": {
        "role": "supplemental-and-added-commands-only",
        "workspace": "/opt/recursion-foundry/workspaces/research-20260911-155142",
        "evidence_root": "/var/lib/recursion-foundry/campaigns/research-20260911-155142",
        "identity_evidence_required": ["Linux/WSL execution truthfully recorded", "no Windows path or host claim anywhere in the receipt"]
      }
    },
    "command_source": {
      "kind": "external-authoritative-inherited-gate-definition",
      "location": "UNRESOLVED",
      "sha256": "UNRESOLVED",
      "rule": "The manifest is not executable until the authoritative 87-command definition is imported from the inherited gate records in the Windows repo and bound here by path plus sha256. Absent entries stay UNRESOLVED; they are never reconstructed from memory or inference."
    },
    "windows_commands": {
      "count_required": 87,
      "batch07_required": 50,
      "entries": [],
      "entries_status": "UNRESOLVED_PENDING_AUTHORITATIVE_SOURCE",
      "per_entry_required_keys": ["ordinal", "command_id", "argv", "cwd_windows_native", "timeout_seconds", "batch07", "receipt_fields"],
      "per_entry_rules": ["ordinal is 1..87 unique", "argv recorded exactly as executed on Windows", "cwd_windows_native recorded in native Windows form, never the /mnt/c alias", "batch07 flags must sum to exactly 50"]
    },
    "native_supplemental_checks": [
      {"check_id": "wsl-unittest", "host": "wsl-native", "satisfies_inherited": false, "note": "full suite under WSL; distinct skip profile"},
      {"check_id": "wsl-source-pycompile", "host": "wsl-native", "satisfies_inherited": false},
      {"check_id": "diff-check", "host": "wsl-native", "satisfies_inherited": false},
      {"check_id": "candidate-cleanliness-ancestry", "host": "wsl-native", "satisfies_inherited": false}
    ],
    "native_added_commands_ref": {
      "rule": "Successor-gate additions (new checker, controls, retained audits) are native commands governed by the canonical budget plan, phase manifests and dual Sol xhigh prospective reviews per controller-proposal-01; their charges are separate from the 655520 inherited-pair reserve.",
      "source": "UNRESOLVED: native-scientific-budget-01.json and per-command phase manifests do not yet exist"
    },
    "binding_rules": [
      "manifest_sha256 binds candidate, candidate_tree, command_source sha256, all 87 windows_commands entries and every native_supplemental/native_added entry",
      "every per-command receipt embeds manifest_sha256, candidate, its ordinal/command_id and its host block",
      "a gate receipt embeds the ordered sha256 list of its 87 command receipts; a successor-gate receipt additionally embeds the sha256 list of added-command receipts",
      "receipts are hash-linked and append-only; any repair creates a new receipt identity, never an edit"
    ],
    "ready": false,
    "blocking": [
      "authoritative 87-command source absent from tracked evidence",
      "final exact candidate not frozen (publication state OPEN_MOVING_CANDIDATE)",
      "native-scientific-budget-01.json, native-source-closure-02.json, phase manifests and two fresh Sol xhigh prospective reviews absent",
      "scientific admission remains BLOCKED_NO_EXECUTION_AUTHORIZED"
    ]
  },

  "receipt_binding": {
    "windows_gate_receipt": {
      "required_keys": ["schema", "campaign", "parent_goal", "candidate", "candidate_tree", "manifest_sha256", "host", "gate_ordinal", "commands", "started_utc", "finished_utc", "status", "scientific_approval"],
      "host_block_required": {"os": "windows", "repo_path": "native Windows form only", "identity_capture": "recorded at execution time on the host"},
      "command_receipt_required_keys": ["ordinal", "command_id", "argv", "cwd_windows_native", "exit_code", "output_sha256", "log_sha256", "elapsed_seconds", "status"],
      "status_rule": "PASS only when all 87 commands verifiably executed on windows-primary against the exact candidate and passed; a receipt claiming PASS without per-command executed evidence is invalid, and a partial or interrupted run is retained as its own non-PASS identity, never counted",
      "timing_rule": "admission window 4800s per gate; measured envelope derives from Windows durations 3771.077387s/3576.111586s"
    },
    "wsl_supplemental_receipt": {
      "required_flags": {"full_gate_equivalence": false, "scientific_approval": false},
      "permitted_status_values": ["SUPPLEMENTAL_PASS", "SUPPLEMENTAL_FAIL", "UNRESOLVED", "PASS_LOCAL_RESEARCH_ONLY", "FAILED_RETAINED", "UNKNOWN_RETAINED"],
      "forbidden": "may never satisfy, replace, rename or be aggregated into a full87 gate receipt; native supplemental evidence accompanies the Windows gate, it is never the gate"
    },
    "cross_host_witness": {
      "rule": "The native side may retain byte-exact copies of Windows receipts observed read-only through the /mnt/c mount. A witness record stores the receipt sha256, the observation alias path and the receipt's own declared native Windows path as separate fields. The receipt's internal paths are never rewritten to the alias form and the alias is never recorded as the executing path.",
      "verification": "native verification is hash-comparison and schema-checking of retained copies only; it confers no transfer of ownership"
    },
    "anti_forgery_invariants": [
      "no fake host identity: a receipt whose host block claims Windows must be minted by execution on the Windows host; native receipts must carry the WSL host identity",
      "no path monkeypatching or rewriting: native Windows form and /mnt/c alias are never substituted for each other inside any receipt",
      "no receipt rewriting: a retained receipt is immutable; corrections are new linked identities",
      "no unrun PASS: PASS requires per-command executed evidence bound by output/log digests; absent or unobserved commands yield UNRESOLVED or retained non-PASS, never omission",
      "no refund or retry identity: post-reservation failures and unknowns are retained per controller-proposal-01 ledger rules"
    ]
  },

  "succession_and_admission": {
    "successor_gate_composition": "A counted successor gate = the Windows-owned 87-command receipt pair (both complete gates) plus the native added checker/controls/retained-audit receipts, all bound to one exact candidate and one manifest_sha256, followed by the two owned retained receipt/source audits and two independent Sol xhigh final reviews.",
    "current_state": "OPEN: publication candidate is moving; no immutable exact-current-candidate Windows or WSL full-gate receipt exists; scientific admission is BLOCKED_NO_EXECUTION_AUTHORIZED.",
    "deadline_pressure": "Two ~4800s Windows gate admissions plus 600s finalization sit inside the 10200s reserve against the immutable 2026-09-11T23:51:42Z deadline; feasibility is a live constraint, not a settled fact."
  },

  "unresolved": [
    "Exact argv/cwd/env/timeout/receipt shape of each of the 87 inherited commands and the identity of the 50 Batch07 subset: absent from tracked evidence.",
    "Location and sha256 of the authoritative inherited gate definition/manifest in the Windows repo.",
    "The Windows-side runner that mints gate receipts and the concrete host-identity capture mechanism it uses.",
    "Per-command host-neutrality analysis: which of the 87 could in principle run host-neutral (none assumed).",
    "Whether successor-gate added commands must also produce a Windows-side presence, or are native-only under the native qualified runtime; the contract requires additions but does not fix their host.",
    "Final exact candidate commit/tree, and whether the Windows review worktree will be synchronized to it cleanly.",
    "Unreachable-witness rates on real shards for retained controls; unavailable branches force INCOMPLETE_FIXED_CONTROL_SUITE and remain unresolved.",
    "Control-to-global-ledger mapping and whether the conditional 76582-unit control margin is sufficient; the all-additive estimate already exceeds the ceiling."
  ],

  "limitations": [
    "This is a source-only design proposal; nothing herein is executed, admitted, or scientifically accepted, and it does not claim gate completion or equivalence.",
    "The packet contains no per-command detail for the 87 inherited commands; the manifest is therefore a binding design that becomes executable only after the authoritative command source is attached by hash.",
    "Tracked evidence describes the Windows gate's existence, duration and obligations but not its internal receipt schema; the required-key lists above are the minimum binding contract, not a claim about the historical schema.",
    "The /mnt/c mount gives observation, not execution or truthful Windows path identity; cross-host witnessing cannot convert a native run into a Windows gate.",
    "Ruff is absent natively, so the qualified lint route has no WSL supplemental; only unittest/pycompile/diff style checks are duplicable.",
    "Windows host availability, the Windows worktree's final-candidate synchronization, and the Windows-side audit ownership are outside native control and remain open host limitations."
  ]
}
